import numpy as np

N = 45

def check_coloring(M):
    """
    Checks if the coloring scheme C(i, j, k) = (i + j + k) % M satisfies the gnome's constraint.
    Indices i, j, k range from 0 to N-1.
    """

    # 1. Check Z-slices (constant k)
    z_sets = []
    for k in range(N):
        colors_k = set()
        for i in range(N):
            for j in range(N):
                color = (i + j + k) % M
                colors_k.add(color)
        z_sets.append(colors_k)

    if not z_sets:
        return False, 0 # Should not happen for N=45

    target_set_z = z_sets[0]
    for s in z_sets:
        if s != target_set_z:
            # print(f"Z-slice failed. Target size: {len(target_set_z)}, current size: {len(s)}")
            return False, 0

    # 2. Check Y-slices (constant j)
    y_sets = []
    for j in range(N):
        colors_j = set()
        for i in range(N):
            for k in range(N):
                color = (i + j + k) % M
                colors_j.add(color)
        y_sets.append(colors_j)

    target_set_y = y_sets[0]
    for s in y_sets:
        if s != target_set_y:
            # print(f"Y-slice failed. Target size: {len(target_set_y)}, current size: {len(s)}")
            return False, 0

    # 3. Check X-slices (constant i)
    x_sets = []
    for i in range(N):
        colors_i = set()
        for j in range(N):
            for k in range(N):
                color = (i + j + k) % M
                colors_i.add(color)
        x_sets.append(colors_i)

    target_set_x = x_sets[0]
    for s in x_sets:
        if s != target_set_x:
            # print(f"X-slice failed. Target size: {len(target_set_x)}, current size: {len(s)}")
            return False, 0

    # 4. Final check: all target sets must be equal
    if target_set_z != target_set_y or target_set_z != target_set_x:
        # This should theoretically not happen if M is the number of colors used, but check anyway
        return False, 0

    # If successful, the number of colors is the size of the set
    return True, len(target_set_z)

# Test M=2 and M=3
result_m2, colors_m2 = check_coloring(2)
print(f"M=2: Constraint holds: {result_m2}. Number of colors: {colors_m2}")

result_m3, colors_m3 = check_coloring(3)
print(f"M=3: Constraint holds: {result_m3}. Number of colors: {colors_m3}")

# Test the coloring pattern C(i, j, k) = (i + j + k) mod K + 1 for N=2

N = 2
K_test = 4

# Coordinates i, j, k run from 0 to N-1 (i.e., 0 or 1)
colors = {}
for i in range(N):
    for j in range(N):
        for k in range(N):
            # Using modulo K_test for the color index
            colors[(i, j, k)] = (i + j + k) % K_test + 1

# 1. Calculate XY slices (fixed k)
S_xy = {}
for k in range(N):
    slice_colors = set()
    for i in range(N):
        for j in range(N):
            slice_colors.add(colors[(i, j, k)])
    S_xy[k] = slice_colors

# 2. Calculate YZ slices (fixed i)
S_yz = {}
for i in range(N):
    slice_colors = set()
    for j in range(N):
        for k in range(N):
            slice_colors.add(colors[(i, j, k)])
    S_yz[i] = slice_colors

# 3. Calculate ZX slices (fixed j)
S_zx = {}
for j in range(N):
    slice_colors = set()
    for i in range(N):
        for k in range(N):
            slice_colors.add(colors[(i, j, k)])
    S_zx[j] = slice_colors

# Check if the set of unique color sets is identical
Set_A = set(frozenset(s) for s in S_xy.values())
Set_B = set(frozenset(s) for s in S_yz.values())
Set_C = set(frozenset(s) for s in S_zx.values())

print(f"N={N}, K={K_test}")
print(f"Set A (XY profiles): {Set_A}")
print(f"Set B (YZ profiles): {Set_B}")
print(f"Set C (ZX profiles): {Set_C}")

if Set_A == Set_B and Set_B == Set_C:
    print("Constraint satisfied.")
else:
    print("Constraint failed.")

